<!-- Generated by pfy-scaffolding | 테스트 화면 (TestScreen) | list | 2026-06-02T09:11:59.519131+00:00 -->
<template>
  <StandardListTemplate :loading="state.loading">
    <!-- ① 화면 제목: 테스트 화면 -->
    <template #title>
      <ContentHeader title="테스트 화면" />
    </template>

    <!-- ② 검색 조건 폼 -->
    <template #search>
      <SearchForm>
        <SearchFormRow>
          <SearchFormLabel>이름</SearchFormLabel>
          <SearchFormField name="name">
            <SearchFormContent>
              <InputText v-model="searchParams.name" placeholder="이름 검색" style="width: var(--form-element-width)" />
            </SearchFormContent>
          </SearchFormField>
        </SearchFormRow>
        <template #buttons>
          <Button class="submit-button" label="조회" icon="pi pi-search" @click="onSearch" />
          <Button label="초기화" severity="secondary" variant="outlined" @click="onReset" />
        </template>
      </SearchForm>
    </template>

    <!-- ③ 조회 결과 그리드 (default slot) -->
    <DataTable
      :value="pagedRows"
      :loading="state.loading"
      selectionMode="single"
      v-model:selection="state.selectedRow"
      scrollable
      scrollHeight="flex"
      @row-select="onRowSelect"
    >
        <Column field="id" header="No" style="width: 60px" />
        <Column field="name" header="이름" />
    </DataTable>

    <!-- ④ 페이지네이션 -->
    <template #pagination>
      <Paginator
        :rows="state.pageSize"
        :totalRecords="filteredRows.length"
        :rowsPerPageOptions="[20, 50, 100]"
        @page="onPageChange"
      />
    </template>
  </StandardListTemplate>

  <!-- ⑤ 상세 패널 (선택된 행 아래에 표시) -->
  <div v-if="state.selectedRow" class="mockup-detail">
    <h3 class="mockup-detail__title">상세 정보</h3>
    <div class="mockup-detail__body">

    </div>
    <div class="mockup-detail__actions">
      <Button label="수정" icon="pi pi-pencil" severity="secondary" variant="outlined" @click="onEdit" />
      <Button label="삭제" icon="pi pi-trash" severity="danger" @click="onDelete" />
    </div>
  </div>
</template>

<script lang="ts" setup>
import { ref, reactive, computed } from 'vue';
import { StandardListTemplate } from '@/components/templates';
import ContentHeader from '@/components/common/contentHeader/ContentHeader.vue';
import { SearchForm, SearchFormRow, SearchFormLabel, SearchFormField, SearchFormContent } from '@/components/common/searchForm';
import { DataTable } from '@/components/common/dataTable2';
import Paginator from '@/components/common/paginator/Paginator.vue';
import Column from 'primevue/column';
import { Button } from '@/components/common/button';
import { InputText } from '@/components/common/inputText';

// ─────────────────── Types ──────────────────────────────────────────────────────────
interface RowItem {
  id: number;
  name: string;
}

// ─────────────────── Mock Data (API 연동 전 임시) ────────────────────────
const MOCK_DATA: RowItem[] = [
  { id: 1, name: '이름 1번 항목' },
  { id: 2, name: '이름 2번 항목' },
  { id: 3, name: '이름 3번 항목' },
  { id: 4, name: '이름 4번 항목' },
  { id: 5, name: '이름 5번 항목' },
  { id: 6, name: '이름 6번 항목' },
  { id: 7, name: '이름 7번 항목' },
  { id: 8, name: '이름 8번 항목' },
  { id: 9, name: '이름 9번 항목' },
  { id: 10, name: '이름 10번 항목' },
  { id: 11, name: '이름 11번 항목' },
  { id: 12, name: '이름 12번 항목' },
  { id: 13, name: '이름 13번 항목' },
  { id: 14, name: '이름 14번 항목' },
  { id: 15, name: '이름 15번 항목' },
  { id: 16, name: '이름 16번 항목' },
  { id: 17, name: '이름 17번 항목' },
  { id: 18, name: '이름 18번 항목' },
  { id: 19, name: '이름 19번 항목' },
  { id: 20, name: '이름 20번 항목' },
];

// ─────────────────── Options ────────────────────────────────────────────────────────


// ─────────────────── State ──────────────────────────────────────────────────────────
const allRows = ref<RowItem[]>([...MOCK_DATA]);

const state = reactive({
  loading:     false,
  selectedRow: null as RowItem | null,
  pageSize:    20,
  page:        { first: 0, rows: 20 },
});

const searchParams = reactive({
  name: '',
});

// ─────────────────── Computed ───────────────────────────────────────────────────────
const filteredRows = computed<RowItem[]>(() => {
  let rows = allRows.value;
  if (searchParams.name) rows = rows.filter(r => r.name.includes(searchParams.name));
  return rows;
});

const pagedRows = computed<RowItem[]>(() =>
  filteredRows.value.slice(state.page.first, state.page.first + state.pageSize)
);

// ─────────────────── Handlers ───────────────────────────────────────────────────────
function onSearch(): void {
  state.page        = { first: 0, rows: state.pageSize };
  state.selectedRow = null;
}

function onReset(): void {
  Object.assign(searchParams, { name: '' });
  onSearch();
}

function onRowSelect(event: { data: RowItem }): void {
  state.selectedRow = event.data;
}

function onPageChange(event: { first: number; rows: number }): void {
  state.page = event;
}

function onEdit(): void {
  // TODO: 수정 화면으로 이동 또는 모달 오픈
  console.log('[scaffold] onEdit →', state.selectedRow);
}

function onDelete(): void {
  if (!state.selectedRow) return;
  allRows.value     = allRows.value.filter(r => r.id !== state.selectedRow!.id);
  state.selectedRow = null;
}
</script>
